const beforeCorePrograms=render;
render=function(){const n=Number(location.hash.split('/')[1]);if(!location.hash.startsWith('#program/')||n<2||n>11)return beforeCorePrograms();document.getElementById('app').innerHTML=integratedShell('core-program',heading('Program design','Loading…'),model.role);fetch('data/core-programs.json').then(r=>{if(!r.ok)throw Error('Program design unavailable');return r.json();}).then(items=>{if(location.hash!=='#program/'+n)return;const p=items.find(x=>x.program===n);document.getElementById('app').innerHTML=integratedShell('core-program',heading(p.title,'Scholarion Academy · Draft curriculum')+`<section class="card prose"><a href="#catalog">Catalog</a> · <a href="#program-studio">Instructor design studio</a><p>${p.totalWeeks} weeks · ${p.courses.length} ten-week course block(s)</p><p>${esc(p.boundary)}</p><button class="button" disabled>Enrollment not open</button> <a class="button secondary" href="data/core-programs.json" download>Download core design register (JSON)</a><h2>Learning competencies</h2><ul>${p.competencies.map(c=>`<li>${esc(c.text)}</li>`).join('')}</ul><h2>Course curriculum</h2>${p.courses.map(c=>`<h3>${esc(c.title)}</h3>${c.modules.map(m=>`<details><summary>Week ${m.week}: ${esc(m.title)}</summary><ul>${m.outcomes.map(o=>`<li>${esc(o.text)}</li>`).join('')}</ul><p>${esc(m.activity.student)}</p><p>Two mini-lab designs planned; assets pending.</p></details>`).join('')}<p>Planned assessment structure: five assignments, three labs, two projects, eight quizzes, midterm and final assessment. These are mapped plans; question banks and teaching assets are not complete.</p>`).join('')}<h2>Capstone</h2><p>${esc(p.capstone)}</p><ul>${p.rubric.map(r=>`<li>${esc(r.criterion)}: ${r.points} points (proposed)</li>`).join('')}</ul><h2>Pathways and credentials</h2><p>${esc(p.dependencyNotes)}</p><p>Proposed Scholarion Academy Certificate of Completion and capstone skill badge. Completion thresholds need policy reconciliation before issuance; no credential is awarded from this preview.</p><h2>Delivery and support</h2><p>Live sessions, mentorship and career support require confirmed staffing and schedules. Fees and start dates remain unconfigured. No employment or salary outcomes are promised.</p><a href="#help">Local program support</a><h2>Publication gaps</h2><ul>${p.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><p>Cloud Lab launch, grade passback, mastery paths and automatic announcements are not activated by these designs.</p></section>`,model.role);bind();normalizeWorkspace();document.title=p.title+' · Scholarion Academy';}).catch(e=>{document.getElementById('app').textContent=e.message;});};
render();
